insert into public.posts
  (slug, title, dek, excerpt, category, content, author_name, author_bio, read_minutes, tags, is_published, published_at)
values (
  'why-we-write',
  'Why We Write',
  'On the impulse to make thoughts permanent, and what happens when we do.',
  'On the impulse to make thoughts permanent, and what happens when we do.',
  'Essay',
  '<p class="animate-fade-in-up">Writing is strange. You sit alone, moving fingers, arranging symbols — and somehow, across time and space, another mind receives your thought.</p>

        <p class="animate-fade-in-up delay-1">No other species does this. Bees dance. Whales sing. But only humans encode abstract reasoning into persistent marks that outlive the maker.</p>

        <h2>To Think</h2>

        <p class="animate-fade-in-up delay-2">"How do I know what I think until I see what I say?" E.M. Forster asked. The answer: you don''t.</p>

        <p class="animate-fade-in-up delay-3">Thought is slippery. It feels solid in the mind — clear, connected, complete. But try to hold it. It dissolves. Writing pins it down. The act of phrasing forces precision. You discover gaps you didn''t know existed. You find contradictions hiding in the clarity.</p>

        <blockquote class="animate-fade-in-up delay-4">
          "Writing is thinking. To write well is to think clearly. That''s why it''s so hard."
        </blockquote>

        <p class="animate-fade-in-up delay-5">The best writers aren''t the ones with the best thoughts. They''re the ones willing to endure the friction of making thoughts legible — to themselves first, then others.</p>

        <h2>To Remember</h2>

        <p class="animate-fade-in-up">Memory is reconstruction, not retrieval. Every recall rewrites. Writing is the only way to fix a thought in time — to have a conversation with your past self that doesn''t drift.</p>

        <p class="animate-fade-in-up delay-1">I read my notebooks from five years ago and meet a stranger. The writing preserves a version of me that memory has edited. Without it, that self is gone.</p>

        <h2>To Connect</h2>

        <p class="animate-fade-in-up delay-2">A published essay is a message in a bottle. You throw it into the network and wait. Sometimes, someone finds it. They write back: <em>This is exactly what I needed.</em> Or: <em>You''re wrong about this.</em> Either way, a connection forms.</p>

        <p class="animate-fade-in-up delay-3">Writing scales intimacy. One conversation reaches one person. One essay reaches thousands — each reading it alone, in their own context, at their own pace. The writer speaks once; the reader listens many times.</p>

        <h2>To Understand</h2>

        <p class="animate-fade-in-up delay-4">You don''t write because you understand. You write <em>to</em> understand.</p>

        <p class="animate-fade-in-up delay-5">The topic you avoid is the one you need to write about. The idea that feels half-formed is the one that needs the page. Writing is the tool that turns confusion into clarity — but only if you''re willing to write badly first.</p>

        <h2>The Cost</h2>

        <p class="animate-fade-in-up">Writing requires vulnerability. To publish is to say: <em>Here is my mind. Judge it.</em> Most drafts stay private because the risk feels too high.</p>

        <p class="animate-fade-in-up delay-1">But the alternative — never writing, never clarifying, never connecting — is costlier. An unexamined thought is a weight you carry invisibly. Writing sets it down.</p>

        <h2>So Write</h2>

        <p class="animate-fade-in-up delay-2">Not for audience. Not for legacy. For the thinking it forces. For the self it reveals. For the connections it enables.</p>

        <p class="animate-fade-in-up delay-3">Write badly. Write privately. Write regularly. The geometry of the habit matters more than the quality of any single piece.</p>

        <p class="animate-fade-in-up delay-4">You write to discover what you think. And in discovering, you become someone who thinks.</p>',
  'Alex Chen',
  'Writer, reader, occasional builder of things.',
  6,
  ARRAY['Writing', 'Craft', 'Creativity']::text[],
  true,
  '2026-08-28'::timestamptz
)
